package com.cpf.starter.objectstorage;import java.nio.file.*;import java.util.*;import software.amazon.awssdk.core.sync.*;import software.amazon.awssdk.services.s3.S3Client;import software.amazon.awssdk.services.s3.model.*;public final class CpfObjectStorageClient {private final S3Client s3;private final CpfObjectStorageProperties p;public CpfObjectStorageClient(S3Client s,CpfObjectStorageProperties p){s3=s;this.p=p;}public PutObjectResponse upload(String key,Path file)throws java.io.IOException{safe(key);long size=Files.size(file);if(size>p.getMaxBytes())throw new IllegalArgumentException("object limit");return s3.putObject(PutObjectRequest.builder().bucket(p.getBucket()).key(key).checksumAlgorithm(ChecksumAlgorithm.SHA256).build(),RequestBody.fromFile(file));}public void download(String key,Path target){safe(key);s3.getObject(GetObjectRequest.builder().bucket(p.getBucket()).key(key).build(),ResponseTransformer.toFile(target));}public List<String> list(String prefix){safePrefix(prefix);return s3.listObjectsV2(ListObjectsV2Request.builder().bucket(p.getBucket()).prefix(prefix).build()).contents().stream().map(S3Object::key).toList();}public void move(String source,String target){safe(source);safe(target);s3.copyObject(CopyObjectRequest.builder().sourceBucket(p.getBucket()).sourceKey(source).destinationBucket(p.getBucket()).destinationKey(target).build());delete(source);}public void delete(String key){safe(key);s3.deleteObject(DeleteObjectRequest.builder().bucket(p.getBucket()).key(key).build());}private static void safe(String k){if(k==null||k.isBlank()||k.startsWith("/")||k.contains(".."))throw new SecurityException("unsafe object key");}private static void safePrefix(String k){if(k!=null&&!k.isBlank())safe(k);}}
